import 'package:flutter/material.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:stayfinder/models/stay_cart_model.dart';

import '../models/stay_model.dart';

class CartProvider extends ChangeNotifier {
  final Box<StayModel> cartBox;
  String errorMsg = "";
  bool isAdded = false;
  bool isRemoved = false;

  CartProvider({required this.cartBox});
  List<StayModel> getAllItemsInCart() {
   // print("cartBox.values.toList in getAllItemsInCar:: ${cartBox.values.toList()}");
    return cartBox.values.toList();
  }

  void addToCart({required StayModel cartItem}) async {
    final existingItemIndex = cartBox.values.toList().indexWhere(
      (item) => item.id == cartItem.id,
    );
    if (existingItemIndex != -1) {
      final existingItem = cartBox.getAt(existingItemIndex);
      existingItem!.save();
      errorMsg = "This item has already been added to the cart.";
      getAllItemsInCart();
      notifyListeners();
    } else {
      await cartBox.put(cartItem.id, cartItem);
      isAdded = true;
       getAllItemsInCart();
      notifyListeners();
    }
    if (isAdded == false) {
      errorMsg = "Failed to add this Stay into Cart";
      notifyListeners();
    }
  }

  void removeFromCart({required int idItemRemoved}) async {
    await cartBox.delete(idItemRemoved);
    isRemoved = true;
    getAllItemsInCart();
    notifyListeners();
  }



  void getTotalPrice(){}
}
